\label{lem:cube}
Let $n\geq2$ and $A\in\mathbf M_n(S_7)$. Then
\begin{equation}\label{eq:cube}
A^3=
\begin{cases}
J_n,&A=J_n,\\
\Omega_n,&A\neJ_n.
\end{cases}
\end{equation}

\label{lem:factor}
Let $n\geq2$ and $X,Y\in\mathbf M_n(S_7)$.
\begin{enumerate}
\item If $XY=J_n$, then $X=Y=J_n$.
\item The equality $XY=K_n$ holds if and only if there exist
$u_1,\ldots,u_n\in\{1,a\}$ such that
\begin{equation}\label{eq:profile}
X_{rk}=u_k,\qquad Y_{ks}=\overline{u_k}
\qquad(1\leq r,k,s\leq n).
\end{equation}
\end{enumerate}

\label{lem:embedding}
Let $S$ be an ai-semiring and let $2\leq m\leq n$. Then
$\mathbf M_m(S)$ embeds into $\mathbf M_n(S)$.

Choose a surjection $\sigma:\{1,\ldots,n\}\to\{1,\ldots,m\}$,
and define $\Phi(A)_{ij}=A_{\sigma(i),\sigma(j)}$.
Surjectivity makes $\Phi$ injective, and it preserves addition
entrywise. Moreover, additive idempotence gives
\begin{align*}
(\Phi(A)\Phi(B))_{ij}
&=\sum_{k=1}^n A_{\sigma(i),\sigma(k)}B_{\sigma(k),\sigma(j)}\\
&=\sum_{r=1}^m A_{\sigma(i),r}B_{r,\sigma(j)}
=\Phi(AB)_{ij}.
\end{align*}
Indeed, every index $r$ occurs at least once as $\sigma(k)$,
and repeated summands may be deleted. Thus $\Phi$ is an embedding.

\label{prop:higher}
For every $n\geq3$, the ai-semiring $\mathbf M_n(S_7)$ does not
satisfy~\eqref{eq:identity}.
